FSAMPLE=formula('N = f_s T; f_N = f_s/2; Q = 2^B',{'N':'number of samples over duration T when the product is integral','f_s':'sampling rate','T':'duration','f_N':'Nyquist frequency','Q':'number of amplitude codes','B':'bits per sample'},{'N,Q,B':'dimensionless counts','f_s,f_N':'Hz','T':'s'},['Uniform sampling; integer bit depth; code count does not specify a quantizer range.'])
FFRAME=formula('F = 1 + floor((N−L)/H)',{'F':'number of complete unpadded frames','N':'input sample count','L':'frame length','H':'hop between frame starts','floor':'greatest integer not exceeding its argument'},{'F,N,L,H':'dimensionless counts'},['N ≥ L > 0; positive integer H; starts at sample zero; retain only complete frames.'])
FHAM=formula('w[n] = 0.54 − 0.46 cos(2πn/L); y[n] = w[n]s[n]',{'w[n]':'periodic Hamming weight at sample n','n':'zero-based sample index','L':'window length in samples','s[n]':'input sample','y[n]':'windowed sample'},{'w[n],n,L':'dimensionless','s[n],y[n]':'same amplitude units'},['0 ≤ n < L; periodic convention printed in the lecture, not the symmetric L−1 convention.'])
FDFT=formula('X[k] = Σ_(n=0)^(N−1) x[n] exp(−j2πkn/N); f_k = k f_s/N',{'X[k]':'complex DFT coefficient at bin k','x[n]':'input sample','n,k':'sample and frequency-bin indices','N':'DFT length','j':'imaginary unit','f_s':'sampling rate','f_k':'nonnegative bin-frequency label before interpreting negative-frequency aliases'},{'X[k],x[n]':'input amplitude units under the unnormalized DFT convention','n,k,N,j':'dimensionless','f_s,f_k':'Hz'},['Unnormalized forward DFT; uniform sampling; bin-frequency interpretation restricted to the stated nonnegative-frequency bins.'])
FMEL=formula('m = 1127 ln(1+f/700); f = 700(exp(m/1127)−1)',{'m':'Mel coordinate in the displayed convention','f':'physical frequency','ln':'natural logarithm','exp':'natural exponential'},{'f,700':'Hz','m,1127':'mel'},['f ≥ 0; this is the displayed convention, not an assertion about every library default.'])
FATT=formula('A = softmax(QKᵀ/√d_k); O = AV',{'Q':'T_q by d_k query matrix from decoder states','K':'T_a by d_k key matrix from encoder states','V':'T_a by d_v value matrix from encoder states','A':'T_q by T_a row-normalized attention weights','O':'T_q by d_v attention output','T_q,T_a':'query and acoustic-key sequence lengths','d_k,d_v':'key and value feature dimensions','softmax':'row-wise normalized exponentials over acoustic keys'},{'Q,K,V,A,O':'dimensionless learned representations or weights in this model','T_q,T_a,d_k,d_v':'dimensionless counts'},['One head; no excluded acoustic keys in the added examples.'])
FSCORE=formula('S(Y|X) = log P(Y|X)/|Y|_c + λ log P_LM(Y)',{'S(Y|X)':'candidate score','Y':'candidate text sequence','X':'acoustic input','P(Y|X)':'conditional acoustic-model sequence probability','|Y|_c':'positive number of characters in Y','P_LM(Y)':'external language-model sequence probability','λ':'external-language-model weight','log':'one consistent logarithm convention'},{'S(Y|X),P(Y|X),P_LM(Y),λ':'dimensionless','|Y|_c':'dimensionless character count'},['Literal source rule: only the acoustic log term is length-normalized; no claim that this is default Whisper decoding.'])
