FCONV=formula('z[j] = Σ_(i=−p)^p x[j+i]w[i+p]; T_out = floor((T+2P−D(K−1)−1)/S)+1',{'z[j]':'output at temporal position j in the displayed stride-one scalar rule','x[j+i]':'input sample or scalar feature, zero outside the declared input','w[i+p]':'kernel coefficient without reversing order','p':'kernel half-width, with K=2p+1 in the first equation','j,i':'output position and local offset','T':'input temporal length','T_out':'output temporal length','P':'zero padding on each side','D':'dilation','K':'kernel length','S':'stride','floor':'greatest integer not exceeding its argument'},{'x,z':'feature units under dimensionless kernel weights','w':'dimensionless','j,i,p,T,T_out,P,D,K,S':'dimensionless index or sample counts'},['No bias in the scalar example; second formula is the general discrete length rule; do not confuse kernel radius p with arbitrary padding P.'])
